{"results": [{"id": "hp_doc_54f9224a80ae6dad9aecb00280ff452d5386b768bf9b3908add49e1e5e16adbc", "title": "Chichester, New Hampshire", "text": "Chichester is a town in Merrimack County, New Hampshire, United States. The population was 2,523 at the 2010 census.", "score": 32.294}, {"id": "hp_doc_bf2ee73dfb7763fb5bf43eff9a0b35682116555931c652eda842d902cea0c553", "title": "Rumney, New Hampshire", "text": "Rumney is a town in Grafton County, New Hampshire, United States. The population was 1,480 at the 2010 census. The town is located at the southern edge of the White Mountain National Forest.", "score": 17.6384}, {"id": "hp_doc_1b303fc12eb41e2051a9f65a9bd31197175728bdd5b2353ee02518bb2e210c7e", "title": "Stinson Lake, New Hampshire", "text": "Stinson Lake is an unincorporated community in the town of Rumney in Grafton County, New Hampshire, United States. It is located at the south end of Stinson Lake, around the lake's outlet. The village is 4 mi north of the village of Rumney, via Stinson Lake Road.", "score": 12.1554}], "remaining_searches": 1}
